function borrow(a: f64[]): ReadSpan<f64> {
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  return v;
}
function forward(a: f64[]): ReadSpan<f64> {
  return borrow(a);
}
export function entry(): f64 {
  const a: f64[] = [1];
  forward(a);
  const w: ReadSpan<f64> = forward(a);
  return 1;
}

